window.__votdWeek && window.__votdWeek({"week":"2029-04-23","reading":"Doctrine and Covenants 37–40","days":[{"d":"2029-04-23","ref":"D&C 37:1","b":"D&C","c":37,"v":1,"he":"הִנֵּה אֲנִי אֹמֵר לָכֶם לֹא נָכוֹן בִּי כִּי תְתַרְגְּמוּ עוֹד עַד לֶכְתְּכֶם אֶל אוֹהָיוֹ וְזֹאת מִפְּנֵי הָאוֹיֵב וּלְמַעַנְכֶם׃","en":"Behold, I say unto you that it is not expedient in me that ye should translate any more until ye shall go to the Ohio, and this because of the enemy and for your sakes."},{"d":"2029-04-24","ref":"D&C 37:2","b":"D&C","c":37,"v":2,"he":"וְעוֹד אֲנִי אֹמֵר לָכֶם לֹא תֵלְכוּ עַד אֲשֶׁר הִטַּפְתֶּם בְּשׂוֹרָתִי בַּמְּקוֹמוֹת הָהֵם וְחִזַּקְתֶּם אֶת־הַכְּנֵסִיָּה בְּכׇל מָקוֹם אֲשֶׁר נִמְצֵאת וּבְיֹתֶר בְּקוֹלֶסְוִיל כִּי הִנֵּה מִתְפַּלְּלִים הֵם אֵלַי בֶּאֱמוּנָה רַבָּה׃","en":"And again, I say unto you that ye shall not go until ye have preached my gospel in those parts, and have strengthened up the church whithersoever it is found, and more especially in Colesville; for, behold, they pray unto me in much faith."},{"d":"2029-04-25","ref":"D&C 38:16","b":"D&C","c":38,"v":16,"he":"וְלִישׁוּעַתְכֶם אֲנִי נֹתֵן לָכֶם מִצְוָה כִּי שָׁמַעְתִּי תְּפִלּוֹתֵיכֶם וְהָעֲנִיִּים הִתְאוֹנְנוּ לְפָנַי וְאֶת־הָעֲשִׁירִים עָשִׂיתִי וְכׇל בָּשָׂר לִי וְאֵינֶנִּי מַכִּיר פָּנִים׃","en":"And for your salvation I give unto you a commandment, for I have heard your prayers, and the poor have complained before me, and the rich have I made, and all flesh is mine, and I am no respecter of persons."},{"d":"2029-04-26","ref":"D&C 38:21","b":"D&C","c":38,"v":21,"he":"אַךְ אָמֵן אֲנִי אֹמֵר לָכֶם כִּי בַזְּמַן לֹא יִהְיֶה לָכֶם מֶלֶךְ וְלֹא מוֹשֵׁל כִּי אֲנִי אֶהְיֶה מַלְכְּכֶם וְאֶשְׁמֹר עֲלֵיכֶם׃","en":"But, verily I say unto you that in time ye shall have no king nor ruler, for I will be your king and watch over you."},{"d":"2029-04-27","ref":"D&C 39:9","b":"D&C","c":39,"v":9,"he":"אַךְ רָאִיתָ יָגוֹן רַב כִּי פְּעָמִים רַבּוֹת מְאַסְתַּנִי בִּגְלַל גַּאֲוָה וּדְאָגוֹת הָעוֹלָם׃","en":"Nevertheless, thou hast seen great sorrow, for thou hast rejected me many times because of pride and the cares of the world."},{"d":"2029-04-28","ref":"D&C 39:21","b":"D&C","c":39,"v":21,"he":"כִּי קְרוֹבָה הָעֵת הַיּוֹם וְהַשָּׁעָה לֹא יֵדַע אִישׁ אַךְ בֹּא תָבוֹא׃","en":"For the time is at hand; the day or the hour no man knoweth; but it surely shall come."},{"d":"2029-04-29","ref":"D&C 40:2","b":"D&C","c":40,"v":2,"he":"וַיְקַבֵּל אֶת־הַדָּבָר בְּשִׂמְחָה אַךְ מַהֵר נִסָּהוּ הַשָּׂטָן וּפַחַד הָרְדִיפָה וּדְאָגוֹת הָעוֹלָם הִסִּיתֻהוּ לִמְאֹס בַּדָּבָר׃","en":"And he received the word with gladness, but straightway Satan tempted him; and the fear of persecution and the cares of the world caused him to reject the word."}]});
